"use strict";(globalThis.webpackChunkdocusaurus||=[]).push([[4652],{4215(e){e.exports=JSON.parse('{"pluginId":"api","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"API Documentation","href":"/api/","docId":"index"},{"type":"category","label":"Classes & Objects","collapsible":true,"collapsed":false,"items":[{"type":"link","label":"Enumerations","href":"/api/classes/Enumerations","docId":"classes/Enumerations"},{"type":"link","label":"EventEmitter","href":"/api/classes/EventEmitter","docId":"classes/EventEmitter"},{"type":"link","label":"Forwarder","href":"/api/classes/Forwarder","docId":"classes/Forwarder"},{"type":"link","label":"Input","href":"/api/classes/Input","docId":"classes/Input"},{"type":"link","label":"InputChannel","href":"/api/classes/InputChannel","docId":"classes/InputChannel"},{"type":"link","label":"Listener","href":"/api/classes/Listener","docId":"classes/Listener"},{"type":"link","label":"Message","href":"/api/classes/Message","docId":"classes/Message"},{"type":"link","label":"Note","href":"/api/classes/Note","docId":"classes/Note"},{"type":"link","label":"Output","href":"/api/classes/Output","docId":"classes/Output"},{"type":"link","label":"OutputChannel","href":"/api/classes/OutputChannel","docId":"classes/OutputChannel"},{"type":"link","label":"Utilities","href":"/api/classes/Utilities","docId":"classes/Utilities"},{"type":"link","label":"WebMidi","href":"/api/classes/WebMidi","docId":"classes/WebMidi"}]}]},"docs":{"classes/Enumerations":{"id":"classes/Enumerations","title":"Enumerations","description":"The Enumerations class contains enumerations and arrays of elements used throughout the\\rlibrary. All its properties are static and should be referenced using the class name. For\\rexample: Enumerations.CHANNEL_MESSAGES.","sidebar":"tutorialSidebar"},"classes/EventEmitter":{"id":"classes/EventEmitter","title":"EventEmitter","description":"The EventEmitter class provides methods to implement the observable design pattern. This","sidebar":"tutorialSidebar"},"classes/Forwarder":{"id":"classes/Forwarder","title":"Forwarder","description":"The Forwarder class allows the forwarding of MIDI messages to predetermined outputs. When you\\rcall its forward() method, it will send the specified Message object\\rto all the outputs listed in its destinations property.\\r\\rIf specific channels or message types have been defined in the channels or\\rtypes properties, only messages matching the channels/types will be forwarded.\\r\\rWhile it can be manually instantiated, you are more likely to come across a Forwarder object as\\rthe return value of the Input.addForwarder() method.","sidebar":"tutorialSidebar"},"classes/Input":{"id":"classes/Input","title":"Input","description":"The Input class represents a single MIDI input port. This object is automatically instantiated\\rby the library according to the host\'s MIDI subsystem and does not need to be directly\\rinstantiated. Instead, you can access all Input objects by referring to the\\rWebMidi.inputs array. You can also retrieve inputs by using methods such as\\rWebMidi.getInputByName() and\\rWebMidi.getInputById().\\r\\rNote that a single MIDI device may expose several inputs and/or outputs.\\r\\rImportant: the Input class does not directly fire channel-specific MIDI messages\\r(such as noteon or\\rcontrolchange, etc.). The InputChannel\\robject does that. However, you can still use the\\rInput.addListener() method to listen to channel-specific events on multiple\\rInputChannel objects at once.","sidebar":"tutorialSidebar"},"classes/InputChannel":{"id":"classes/InputChannel","title":"InputChannel","description":"The InputChannel class represents a single MIDI input channel (1-16) from a single input\\rdevice. This object is derived from the host\'s MIDI subsystem and should not be instantiated\\rdirectly.\\r\\rAll 16 InputChannel objects can be found inside the input\'s channels\\rproperty.","sidebar":"tutorialSidebar"},"classes/Listener":{"id":"classes/Listener","title":"Listener","description":"The Listener class represents a single event listener object. Such objects keep all relevant","sidebar":"tutorialSidebar"},"classes/Message":{"id":"classes/Message","title":"Message","description":"The Message class represents a single MIDI message. It has several properties that make it\\reasy to make sense of the binary data it contains.","sidebar":"tutorialSidebar"},"classes/Note":{"id":"classes/Note","title":"Note","description":"The Note class represents a single musical note such as \\"D3\\", \\"G#4\\", \\"F-1\\", \\"Gb7\\", etc.\\r\\rNote objects can be played back on a single channel by calling\\rOutputChannel.playNote() or, on multiple channels of the same\\routput, by calling Output.playNote().\\r\\rThe note has attack and release velocities set at 0.5 by default.\\rThese can be changed by passing in the appropriate option. It is also possible to set a\\rsystem-wide default for attack and release velocities by using the\\rWebMidi.defaults property.\\r\\rIf you prefer to work with raw MIDI values (0 to 127), you can use rawAttack and\\rrawRelease to both get and set the values.\\r\\rThe note may have a duration. If it does, playback will be automatically stopped\\rwhen the duration has elapsed by sending a \\"noteoff\\" event. By default, the duration is set to\\rInfinity. In this case, it will never stop playing unless explicitly stopped by calling a\\rmethod such as OutputChannel.stopNote(),\\rOutput.stopNote() or similar.","sidebar":"tutorialSidebar"},"classes/Output":{"id":"classes/Output","title":"Output","description":"The Output class represents a single MIDI output port (not to be confused with a MIDI channel).\\rA port is made available by a MIDI device. A MIDI device can advertise several input and output\\rports. Each port has 16 MIDI channels which can be accessed via the channels\\rproperty.\\r\\rThe Output object is automatically instantiated by the library according to the host\'s MIDI\\rsubsystem and should not be directly instantiated.\\r\\rYou can access all available Output objects by referring to the\\rWebMidi.outputs array or by using methods such as\\rWebMidi.getOutputByName() or\\rWebMidi.getOutputById().","sidebar":"tutorialSidebar"},"classes/OutputChannel":{"id":"classes/OutputChannel","title":"OutputChannel","description":"The OutputChannel class represents a single output MIDI channel. OutputChannel objects are\\rprovided by an Output port which, itself, is made available by a device. The\\rOutputChannel object is derived from the host\'s MIDI subsystem and should not be instantiated\\rdirectly.\\r\\rAll 16 OutputChannel objects can be found inside the parent output\'s\\rchannels property.","sidebar":"tutorialSidebar"},"classes/Utilities":{"id":"classes/Utilities","title":"Utilities","description":"The Utilities class contains general-purpose utility methods. All methods are static and\\rshould be called using the class name. For example: Utilities.getNoteDetails(\\"C4\\").","sidebar":"tutorialSidebar"},"classes/WebMidi":{"id":"classes/WebMidi","title":"WebMidi","description":"The WebMidi object makes it easier to work with the low-level Web MIDI API. Basically, it\\rsimplifies sending outgoing MIDI messages and reacting to incoming MIDI messages.\\r\\rWhen using the WebMidi.js library, you should know that the WebMidi class has already been\\rinstantiated. You cannot instantiate it yourself. If you use the IIFE version, you should\\rsimply use the global object called WebMidi. If you use the CJS (CommonJS) or ESM (ES6\\rmodule) version, you get an already-instantiated object when you import the module.","sidebar":"tutorialSidebar"},"index":{"id":"index","title":"API Documentation","description":"Core Classes","sidebar":"tutorialSidebar"}}}')}}]);